quests[46498] = { id = 46498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fearless Combatant's Felweave Armor" }
quests[46499] = { id = 46499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinnen, was?", description = "Ich hab das Gefühl, sie würden immer noch auf mir herumkrabbeln. Ich habe ein Ei zertreten und plötzlich war ich von Kopf bis Fuß mit Spinnenbabys bedeckt.\n\n<Erschauert.>\n\nDer Schatz liegt da jetzt einfach rum. Der nächste Suchende ist hoffentlich nicht arachnophlibisch... arachnophonetisch? Arachniphant? Ach, er sollte einfach keine Angst vor Spinnen haben!", sourceObjective = "Sucht nach dem erwähnten Schatz in der Kriechergrotte.", progress = "Ich bin immer auf der Suche nach neuen Schätzen!", completion = "Oh, sieh mal einer an! Ihr habt den Schatz beschafft! He... Da sitzt noch eine Spinne auf Eurer Schulter.\n\nDann schauen wir mal, was für einen fantastischen Schatz Ihr mir beschert habt... Das ist alles? Das ist ja wertlos! Behaltet Ihr es.\n\nTja, Pech gehabt. Auf ein Neues.", sourceObjectiveStatus = "unverified-source-field" }
quests[46500] = { id = 46500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Legende aus der Tiefe" }
quests[46501] = { id = 46501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabräuberei", description = "Ich bin keine Grabräuberin, aber ist es eigentlich Grabräuberei, wenn der Schatz einfach auf einem Haufen aus Knochen herumliegt? Ist ja nicht vergraben oder so. Ich halte mich diesmal lieber zurück, nur um sicherzugehen.", sourceObjective = "Sucht nach dem erwähnten Schatz auf dem Seelentrümmerfeld.", progress = "Ich bin immer auf der Suche nach neuen Schätzen!", completion = "Ihr habt in einer Kiste einen Schlüssel entdeckt? Nichts weiter?\n\nDa hat wohl jemand vor Euch alles geplündert und aus Versehen den Schlüssel in die Truhe gesperrt. Also habt Ihr einen Schlüssel für eine Kiste erbeutet, die Ihr bereits ausgeräumt habt. Unglaubliche Leistung... und da behaupten Leute, ich wäre schlecht in meiner Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[46502] = { id = 46502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Hand der Legion" }
quests[46503] = { id = 46503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Lektion in Sachen Schmerz" }
quests[46504] = { id = 46504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Erdrückende Tiefen" }
quests[46505] = { id = 46505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Verloren, aber nicht vergessen" }
quests[46506] = { id = 46506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Leben nach dem Tode" }
quests[46507] = { id = 46507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Der Schreckenspirscher" }
quests[46508] = { id = 46508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Azsharas Einfluss" }
quests[46509] = { id = 46509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuche am Grabmal", description = "Ich hab mir wieder und wieder gesagt: \"Geh nicht in die Nähe der Zitadelle. Geh nicht in die Nähe der Zitadelle.\" Und was hab ich gemacht? Bin zur Zitadelle. Ich hatte schon fast meine Flossen an dieser hübschen Schatztruhe, aber dann haben mich ein paar dieser irren Dämonen weggejagt. Bin gerade so mit Helm und Leben hinausgekommen!", sourceObjective = "Sucht nach dem erwähnten Schatz außerhalb des Grabmals des Sargeras.", progress = "Ich bin immer auf der Suche nach neuen Schätzen!", completion = "Habt Ihr Euch die Mühe gemacht, das Etikett auf dem Trank zu lesen? Ich vermute nicht. Vielleicht findet Ihr ja einen Narren, der Euch dafür bezahlt.\n\nViel Glück beim nächsten Versuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46510] = { id = 46510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffsfriedhof", description = "Ich hab Euch gar nicht gesagt, dass ich bei der ursprünglichen Landung dabei war, bei der wir fast alles verloren haben. Mir ist vollkommen egal, was dort noch ist, an diesen Strand kehre ich nie wieder zurück. Niemals.", sourceObjective = "Sucht nach dem erwähnten Schatz in den Einsamen Tiefen.", progress = "Ich bin immer auf der Suche nach neuen Schätzen!", completion = "Es ist... nass. Dieses Ding ist wahrscheinlich inzwischen wertlos.\n\nGibt es auf dieser verfluchten Insel auch nur einen guten Schatz? Ich mag ja nicht die hellste Kerze auf dem Kuchen sein, aber allmählich fange ich an zu glauben, dass das Verhältnis \"Todesrisiko zu Schatz\" an diesem Ort nicht zu meinen Gunsten ausfällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46511] = { id = 46511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind die Schatzjäger", description = "Ich hab so das Gefühl, als würdet Ihr mich nur ausnutzen, um die besten Schätze zu finden. Na gat, ich verzeihe Euch, aber das war das letzte Mal, dass ich Euch was verrate. Hab ich gerade \"Na gat\" gesagt? Ich meinte natürlich na ga..., ähh, na gut. Verflixt noch mal.\n\nFein. Diesmal habt Ihr mich wohl erwischt. Dann lasst es uns so machen: Ihr holt mir die Truhe von diesen Nagamonstern und ich werde Euch dafür belohnen.", sourceObjective = "Sucht nach dem erwähnten Schatz am Dämonengrollstrand.", progress = "Habt Ihr schon den Schatz besorgt?", completion = "Das ist alles? Habt Ihr sicher nichts anderes gefunden? Einen riesigen Haufen Goldmünzen auf einer Statue aus Diamanten, die eine Schriftrolle mit der Kombination zum Tresor von Eisenschmiede enthält? Das wär so toll gewesen.\n\nNun gut. Ich schätze, ich kann daraus einen Briefbeschwerer machen oder es nach einem Eichhörnchen werfen.\n\nKommt morgen zu mir zurück, dann habe ich einen neuen Auftrag für Euch.", sourceObjectiveStatus = "unverified-source-field" }
